# o6_4 – Antragstellung, Vertragszeitraum, Flächenänderungen, Umstieg, Ausstieg, höhere Gewalt und Sanktionen
package oepul.o6_4

import rego.v1

# O64-CON-001: Vertragszeitraum je Vertragsbeginn (bis 31.12.2028)
contract_period := cp if {
	some cp in cfg.contract_periods
	cp.start_date == measure_input.contract_start_date
}

contract_failures contains f if {
	is_string(measure_input.contract_start_date)
	not contract_period
	f := {"rule_id": "O64-APP-002", "message": sprintf("Vertragsbeginn %v nicht zulässig (Einstieg nur 01.01.2023, 01.01.2024 oder 01.01.2025)", [measure_input.contract_start_date])}
}

# O64-APP-001: Maßnahmenantrag bis 31.12. vor Vertragsbeginn (keine Fristverschiebung, § 5 Abs. 2 GSP-AV)
application_deadline := sprintf("%d-12-31", [contract_start_year - 1])

application_timely if measure_input.application_date <= application_deadline

contract_failures contains f if {
	is_string(measure_input.application_date)
	is_number(contract_start_year)
	not application_timely
	f := {"rule_id": "O64-APP-001", "message": sprintf("Maßnahmenantrag vom %v nach der Frist %v", [measure_input.application_date, application_deadline])}
}

# O64-APP-002: letzter Einstieg Förderjahr 2025 (Antrag bis 31.12.2024)
contract_failures contains f if {
	is_number(contract_start_year)
	contract_start_year > cfg.measure.last_entry_funding_year
	f := {"rule_id": "O64-APP-002", "message": "Einstieg nach dem Förderjahr 2025 nicht mehr möglich"}
}

contract_missing contains field if {
	some field in ["application_date", "contract_start_date"]
	object.get(measure_input, field, null) == null
}

contract_active if {
	count(contract_failures) == 0
	count(contract_missing) == 0
	contract_start_year <= year
	year <= date_year(cfg.measure.contract_end_date)
}

# O64-APP-003: Umstieg in Naturschutz (18) oder Ergebnisorientierte Bewirtschaftung (19) bis 31.12.2025
conversion := object.get(measure_input, "conversion", null)

conversion_valid if {
	is_object(conversion)
	some t in cfg.conversion_targets
	t.measure_number == conversion.target_measure_number
	conversion.contract_change_date <= t.deadline
}

contract_failures contains f if {
	is_object(conversion)
	not conversion_valid
	f := {"rule_id": "O64-APP-003", "message": "Umstieg nur in Naturschutz oder Ergebnisorientierte Bewirtschaftung mit Vertragswechsel spätestens 31.12.2025 möglich"}
}

converted_parcels contains pid if {
	conversion_valid
	some pid in object.get(conversion, "parcel_ids", [])
}

# O64-GEN-013..016: Ausstieg (Abmeldung) aus der mehrjährigen Maßnahme
exit_date := object.get(measure_input, "exit_date", null)

exit_in_current_year if {
	is_string(exit_date)
	date_year(exit_date) == year
}

exit_blocked_by_control if {
	is_string(exit_date)
	announced := object.get(measure_input, "control_announced_or_notified_date", null)
	is_string(announced)
	announced <= exit_date
}

exit_repayment_required if {
	is_string(exit_date)
	not exit_blocked_by_control
	not conversion_valid
	not object.get(measure_input, "exit_without_repayment_recognized", false)
}

# O64-GEN-019..022: Flächenabgang – Toleranz 5 %, höchstens 5 ha, jedenfalls 0,5 ha
area_decrease_ha := d if {
	prev := measure_input.area_previous_year_ha
	curr := measure_input.area_current_year_ha
	lost := object.get(measure_input, "area_lost_disposal_ha", 0)
	conv := object.get(measure_input, "area_allowed_conversion_ha", 0)
	d := max([0, ((prev - curr) - lost) - conv])
}

area_decrease_tolerance_ha := t if {
	prev := measure_input.area_previous_year_ha
	ac := cfg.area_change
	t := max([ac.decrease_tolerance_min_ha, min([(prev * ac.decrease_tolerance_percent) / 100, ac.decrease_tolerance_max_ha])])
}

area_decrease_repayment_ha := area_decrease_ha if area_decrease_ha > area_decrease_tolerance_ha

# O64-GEN-023: Flächenzugang – 2024/2025 zur Gänze, danach max. 50 % auf Basis 2025, jedenfalls 5 ha
area_increase_limit_ha := lim if {
	year > cfg.area_change.increase_base_year
	base := measure_input.area_2025_ha
	inc := max([(base * cfg.area_change.increase_max_percent) / 100, cfg.area_change.increase_min_ha])
	lim := (base + inc) + object.get(measure_input, "area_additions_previously_committed_ha", 0)
}

# O64-GEN-018: Maßnahmenübernahme bis 15.04. (2023 und 2028: 17.04.), Ausweitung max. 50 %
takeover := object.get(measure_input, "takeover", null)

takeover_deadline(y) := sprintf("%d-%v", [y, cfg.takeover.deadline_month_day_2023_2028]) if {
	y in {cfg.takeover.special_year_first, cfg.takeover.special_year_last}
} else := sprintf("%d-%v", [y, cfg.takeover.deadline_month_day])

takeover_failures contains f if {
	is_object(takeover)
	takeover.date > takeover_deadline(date_year(takeover.date))
	f := {"rule_id": "O64-GEN-018", "message": "Maßnahmenübernahme nach dem 15. April (2023/2028: 17. April)"}
}

takeover_failures contains f if {
	is_object(takeover)
	takeover.taker_previously_participating == true
	f := {"rule_id": "O64-GEN-018", "message": "Übernahme nur durch einen bisher nicht an der Maßnahme teilnehmenden Betrieb"}
}

takeover_failures contains f if {
	is_object(takeover)
	takeover.extension_area_ha > (takeover.taken_over_area_ha * cfg.area_change.takeover_max_extension_percent) / 100
	f := {"rule_id": "O64-GEN-018", "message": "Ausweitung auf andere Flächen um mehr als 50 %"}
}

# O64-GEN-030/031: höhere Gewalt – Meldung binnen 3 Wochen, belegt
fm_claims := object.get(input, ["oepul", "force_majeure_claims"], [])

fm_claim_recognized(c) if {
	object.get(c, "documented", false) == true
	deadline_ns := time.add_date(time.parse_ns("2006-01-02", c.able_to_report_date), 0, 0, 7 * cfg.deadlines.force_majeure_notification_weeks)
	time.parse_ns("2006-01-02", c.reported_date) <= deadline_ns
}

fm_claim_recognized(c) if object.get(c, "automatically_recognized", false) == true

excused(v) if {
	some c in fm_claims
	fm_claim_recognized(c)
	v.parcel_id in object.get(c, "parcel_ids", [])
}

# O64-GEN-025/026: Sanktionsstufen bei inhaltlichen Verstößen
level_percent(0) := 1 if year >= 2027

level_percent(0) := 0 if year < 2027

level_percent(l) := pct if {
	l > 0
	some s in cfg.sanction_levels
	s.level == l
	pct := s.reduction_percent
}

finding_percent(f) := level_percent(min([6, f.level + object.get(f, "prior_occurrences_same_obligation", 0)]))

content_reduction_percent := min([
	cfg.sanction_rules.max_cumulated_reduction_percent,
	sum([finding_percent(f) | some f in object.get(measure_input, "assessed_findings", [])]),
])

excluded_from_measure if {
	object.get(measure_input, "full_reductions_in_period", 0) >= cfg.sanction_rules.exclusion_after_full_reductions
}

# O64-GEN-032: Verweigerung der Vor-Ort-Kontrolle
control_refused if object.get(measure_input, "on_site_control_refused", false) == true

# O64-GEN-034: verabsäumter Zahlungsantrag
payment_claim_missing if object.get(measure_input, "payment_claim_submitted", true) == false

payment_claim_obligation_ended if {
	payment_claim_missing
	object.get(measure_input, "payment_claim_overdue_more_than_one_year", false) == true
}

# O64-GEN-035: Übererklärung > 3 % oder > 2 ha → Kürzung um das 1,5fache der Differenz
over_declaration_sanction_ha := s if {
	declared := measure_input.declared_area_ha
	determined := measure_input.determined_area_ha
	diff := declared - determined
	diff > 0
	over_declaration_relevant(diff, determined)
	s := cfg.sanction_rules.over_declaration_factor * diff
}

over_declaration_relevant(diff, determined) if diff > (determined * cfg.sanction_rules.over_declaration_threshold_percent) / 100

over_declaration_relevant(diff, _) if diff > cfg.sanction_rules.over_declaration_threshold_ha

# O64-2026-001: keine o6_4-spezifische Ausnahmeregelung in den AMA-Hinweisen 2026
notices_2026_o6_4_derogation := false

# o6_4 – Teilnahmefähige Flächen und förderwerbende Personen
# Bergmahd-Definition, Seehöhe, Dauersiedlungsgrenze, Ausschlüsse und Zugangsvoraussetzungen.
package oepul.o6_4

import rego.v1

# O64-ELIG-001 / O64-COD-001: nur Bergmahdflächen mit Schlagnutzungsart „Bergmähder"
parcel_failures[pid] contains f if {
	some pid, p in o6_4_parcels
	object.get(mountain_meadow(p), "declared_as_bergmaehder", null) == false
	f := {"rule_id": "O64-ELIG-001", "message": "Schlag ist nicht mit der Schlagnutzungsart „Bergmähder“ beantragt"}
}

# O64-ELIG-002: über der örtlichen Dauersiedlungsgrenze
parcel_failures[pid] contains f if {
	some pid, p in o6_4_parcels
	object.get(mountain_meadow(p), "above_permanent_settlement_limit", null) == false
	f := {"rule_id": "O64-ELIG-002", "message": "Fläche liegt nicht über der örtlichen Dauersiedlungsgrenze"}
}

# O64-ELIG-003: mehr als die Hälfte der Schlagfläche über 1.200 m Seehöhe
parcel_failures[pid] contains f if {
	some pid, p in o6_4_parcels
	share := object.get(mountain_meadow(p), "share_above_1200m_percent", null)
	is_number(share)
	share <= cfg.eligibility_thresholds.min_share_above_1200m_percent_exclusive
	f := {"rule_id": "O64-ELIG-003", "message": sprintf("nur %v %% der Schlagfläche über 1.200 m Seehöhe (erforderlich: mehr als 50 %%)", [share])}
}

# O64-ELIG-004: über der Seehöhe des Heimbetriebes; Ausnahme Almbetriebe
parcel_failures[pid] contains f if {
	some pid, p in o6_4_parcels
	not is_alm_operation
	object.get(mountain_meadow(p), "above_home_farm_elevation", null) == false
	f := {"rule_id": "O64-ELIG-004", "message": "Bergmahdfläche liegt nicht über der Seehöhe des Heimbetriebes"}
}

is_alm_operation if object.get(input, ["farm", "is_alm_operation"], false) == true

# O64-ELIG-005: grenzt in der Regel nicht unmittelbar an eigene Heimbetriebsflächen (Indiz, kein Ausschluss)
parcel_warnings[pid] contains w if {
	some pid, p in o6_4_parcels
	object.get(mountain_meadow(p), "adjacent_to_home_farm_land", false) == true
	w := {"rule_id": "O64-ELIG-005", "message": "Fläche grenzt unmittelbar an Heimbetriebsflächen – Einstufung als Bergmahd prüfen (Regelfall: nicht angrenzend)"}
}

# Fehlende Eingaben für die Bergmahd-Definition
eligibility_fields := [
	"declared_as_bergmaehder",
	"above_permanent_settlement_limit",
	"share_above_1200m_percent",
	"above_home_farm_elevation",
]

parcel_missing[pid] contains field if {
	some pid, p in o6_4_parcels
	some field in definition_missing(p)
}

field_exempt("above_home_farm_elevation") if is_alm_operation

# O64-ELIG-001..004: Schlag erfüllt die Bergmahd-Definition
definition_missing(p) := {field |
	some field in eligibility_fields
	not field_exempt(field)
	object.get(mountain_meadow(p), field, null) == null
}

parcel_is_bergmahd[pid] if {
	some pid, p in o6_4_parcels
	count(object.get(parcel_failures, pid, set())) == 0
	count(definition_missing(p)) == 0
}

# O64-GEN-006: nicht förderfähige Flächen (Nationalparks, OP-/VF-Code, sonstige Ausschlüsse)
parcel_premium_exclusions[pid] contains f if {
	some pid, p in o6_4_parcels
	np := object.get(parcel_oepul(p), "national_park", null)
	some park in cfg.national_parks
	park.key == np
	park.oepul_area_premium_possible == false
	f := {"rule_id": "O64-GEN-006", "message": sprintf("Fläche im Nationalpark %v – keine flächenbezogene ÖPUL-Prämie", [park.name])}
}

parcel_premium_exclusions[pid] contains f if {
	some pid, p in o6_4_parcels
	"OP" in object.get(parcel_oepul(p), "codes", [])
	f := {"rule_id": "O64-GEN-007", "message": "Schlag mit Code OP – keine ÖPUL-Prämie im Förderjahr"}
}

# maßnahmenbezogener OP-Code (Bezeichnung für o6_4 in den Quellen nicht genannt, daher als Flag)
parcel_premium_exclusions[pid] contains f if {
	some pid, p in o6_4_parcels
	object.get(parcel_oepul(p), "measure_specific_op_code_o6_4", false) == true
	f := {"rule_id": "O64-GEN-007", "message": "maßnahmenbezogener OP-Code für o6_4 – keine Prämie für diese Maßnahme"}
}

parcel_premium_exclusions[pid] contains f if {
	some pid, p in o6_4_parcels
	"VF" in object.get(parcel_oepul(p), "codes", [])
	f := {"rule_id": "O64-GEN-006", "message": "Versuchsfläche (Code VF) – im laufenden Antragsjahr keine Prämie"}
}

parcel_premium_exclusions[pid] contains f if {
	some pid, p in o6_4_parcels
	some key in object.get(parcel_oepul(p), "non_eligible_reasons", [])
	some ne in cfg.non_eligible_areas
	ne.key == key
	f := {"rule_id": "O64-GEN-006", "message": sprintf("nicht förderfähige Fläche: %v", [ne.label])}
}

# O64-ELIG-010: Mindestgröße einer förderfähigen Fläche 50 m²
parcel_premium_exclusions[pid] contains f if {
	some pid, p in o6_4_parcels
	p.area_ha < 0.005
	f := {"rule_id": "O64-ELIG-010", "message": "förderfähige Fläche unter 50 m²"}
}

# O64-GEN-002: förderwerbende Person
applicant := object.get(input, ["farm", "applicant"], {})

applicant_failures contains f if {
	applicant.legal_form == "public_body"
	f := {"rule_id": "O64-GEN-002", "message": "Gebietskörperschaften und deren Einrichtungen sind bei dieser Maßnahme nicht förderwerbend"}
}

applicant_failures contains f if {
	some t in cfg.applicant_types
	t.type == applicant.legal_form
	is_number(t.max_public_body_share_percent)
	applicant.public_body_share_percent > t.max_public_body_share_percent
	f := {"rule_id": "O64-GEN-002", "message": "Beteiligung von Gebietskörperschaften über 25 %"}
}

applicant_failures contains f if {
	applicant.is_active_farmer == false
	f := {"rule_id": "O64-GEN-003", "message": "Kein aktiver Landwirt"}
}

applicant_failures contains f if {
	applicant.manages_in_own_name_and_account == false
	f := {"rule_id": "O64-GEN-003", "message": "Betrieb wird nicht im eigenen Namen und auf eigene Rechnung bewirtschaftet"}
}

applicant_failures contains f if {
	applicant.has_disposal_over_areas == false
	f := {"rule_id": "O64-GEN-003", "message": "keine Verfügungsgewalt über die beantragten Flächen"}
}

# O64-GEN-004: Betriebsmindestgröße nur im ersten ÖPUL-Teilnahmejahr
first_participation_year := object.get(input, ["oepul", "first_participation_year"], null)

farm_minimum_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= cfg.farm_minimum_size.protected_cultivation_ha
}

farm_minimum_size_met if {
	object.get(input, ["land", "total_area_ha"], 0) >= cfg.farm_minimum_size.agricultural_area_ha
}

farm_minimum_size_required if first_participation_year == year

applicant_failures contains f if {
	farm_minimum_size_required
	not farm_minimum_size_met
	f := {"rule_id": "O64-GEN-004", "message": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr nicht erreicht (0,50 ha geschützter Anbau oder 1,50 ha landwirtschaftliche Fläche)"}
}

applicant_eligible if count(applicant_failures) == 0

# O64-ELIG-006..008: keine Kombinationspflicht, keine Gesamtteilnahme, keine Mindestteilnahmefläche
combination_obligation := cfg.measure.combination_obligation

all_bergmaehder_required := cfg.measure.all_farm_bergmaehder_required

minimum_participation_area_ha := cfg.measure.minimum_participation_area_ha

# o6_4 – Förderbedingungen (Mahd, Beweidung, Düngung, Pflanzenschutz, Codierung)
# Prüft die jährlichen Bewirtschaftungsauflagen auf allen o6_4-Schlägen, auch in BM0-Jahren.
package oepul.o6_4

import rego.v1

mowing_events_of(p) := events_in_year(object.get(parcel_ops(p), "mowing_events", []))

# O64-OBL-001: Mahd zählt nur bei vollflächiger Mahd mit Verbringung des Mähgutes
qualifying_mowing(e) if {
	object.get(e, "full_area", false) == true
	object.get(e, "cut_material_removed", false) == true
	object.get(e, "mulched", false) == false
}

qualifying_mowings(p) := [e |
	some e in mowing_events_of(p)
	qualifying_mowing(e)
]

qualifying_mowing_this_year[pid] if {
	some pid, p in o6_4_parcels
	count(qualifying_mowings(p)) > 0
}

# Jahre mit vollflächiger Mahd (Historie + laufendes Jahr)
history_mowing_years(p) := {y | some y in object.get(mountain_meadow(p), "full_mowing_years", [])}

full_mowing_years(pid, p) := history_mowing_years(p) | {year} if {
	qualifying_mowing_this_year[pid]
} else := history_mowing_years(p)

# O64-OBL-001: zumindest jedes zweite Jahr vollflächige Mahd inkl. Verbringung (Jahresendbetrachtung)
violations contains v if {
	some pid, p in o6_4_parcels
	is_number(contract_start_year)
	year > contract_start_year
	years := full_mowing_years(pid, p)
	not year in years
	not (year - 1) in years
	v := {"rule_id": "O64-OBL-001", "parcel_id": pid, "message": "keine vollflächige Mahd mit Verbringung des Mähgutes im laufenden und im Vorjahr"}
}

# O64-OBL-002: maximal eine Mahd pro Jahr
violations contains v if {
	some pid, p in o6_4_parcels
	n := count(mowing_events_of(p))
	n > cfg.mowing_rules.max_mowings_per_year
	v := {"rule_id": "O64-OBL-002", "parcel_id": pid, "message": sprintf("%v Mahden im Jahr (maximal 1 zulässig)", [n])}
}

# O64-OBL-003: Mähen und Liegenlassen bzw. Häckseln unzulässig
violations contains v if {
	some pid, p in o6_4_parcels
	some e in mowing_events_of(p)
	object.get(e, "mulched", false) == true
	v := {"rule_id": "O64-OBL-003", "parcel_id": pid, "message": sprintf("Fläche am %v gehäckselt – unzulässig", [e.date])}
}

violations contains v if {
	some pid, p in o6_4_parcels
	some e in mowing_events_of(p)
	object.get(e, "mulched", false) == false
	object.get(e, "cut_material_removed", true) == false
	v := {"rule_id": "O64-OBL-003", "parcel_id": pid, "message": sprintf("Mähgut der Mahd am %v nicht verbracht (liegen gelassen) – unzulässig", [e.date])}
}

# O64-OBL-004/005: Beweidung verboten, Nachweide ab 16. August jährlich zulässig
violations contains v if {
	some pid, p in o6_4_parcels
	some g in object.get(parcel_ops(p), "grazing_events", [])
	date_year(g.start_date) == year
	month_day(g.start_date) < cfg.mowing_rules.post_grazing_earliest_month_day
	v := {"rule_id": "O64-OBL-004", "parcel_id": pid, "message": sprintf("Beweidung ab %v vor dem 16. August – unzulässig", [g.start_date])}
}

post_grazing_allowed(d) if month_day(d) >= cfg.mowing_rules.post_grazing_earliest_month_day

# O64-OBL-006..009: Düngemittel, Klärschlamm, Kalk; Ausnahme Festmist (ursprüngliche Form) und häusliche Abwässer
fertilizer_rule_id("lime") := "O64-OBL-008"

fertilizer_rule_id("solid_manure_dissolved") := "O64-OBL-007"

fertilizer_rule_id(t) := "O64-OBL-006" if not t in {"lime", "solid_manure_dissolved"}

fertilizer_type_allowed(t) if {
	some ft in cfg.fertilizer_types
	ft.type == t
	ft.allowed == true
}

violations contains v if {
	some pid, p in o6_4_parcels
	some a in events_in_year(object.get(parcel_ops(p), "fertilizer_applications", []))
	not fertilizer_type_allowed(a.type)
	v := {"rule_id": fertilizer_rule_id(a.type), "parcel_id": pid, "message": sprintf("Ausbringung von %v am %v – unzulässig", [a.type, a.date])}
}

violations contains v if {
	some pid, p in o6_4_parcels
	some a in events_in_year(object.get(parcel_ops(p), "fertilizer_applications", []))
	a.type == "solid_manure"
	object.get(a, "demand_based", true) == false
	v := {"rule_id": "O64-OBL-007", "parcel_id": pid, "message": sprintf("Festmistausbringung am %v nicht bedarfsgerecht", [a.date])}
}

# Kurzangaben im Profil: Mineraldünger-N > 0 ist auf o6_4-Flächen jedenfalls unzulässig
violations contains v if {
	some pid, p in o6_4_parcels
	n := object.get(parcel_ops(p), ["fertilizer", "mineral_n_kg_per_ha"], null)
	is_number(n)
	n > 0
	v := {"rule_id": "O64-OBL-006", "parcel_id": pid, "message": "mineralische Stickstoffdüngung angegeben – unzulässig"}
}

# O64-OBL-010: Pflanzenschutzmittel nur mit Wirkstoffen gemäß VO (EU) 2018/848
violations contains v if {
	some pid, p in o6_4_parcels
	some a in events_in_year(object.get(parcel_ops(p), "psm_applications", []))
	object.get(a, "only_eu_2018_848_substances", false) == false
	v := {"rule_id": "O64-OBL-010", "parcel_id": pid, "message": sprintf("Pflanzenschutzmittel %v enthält nicht ausschließlich gemäß VO (EU) 2018/848 zulässige Wirkstoffe", [object.get(a, "product", "unbekannt")])}
}

parcel_warnings[pid] contains w if {
	some pid, p in o6_4_parcels
	object.get(parcel_ops(p), "psm_used", false) == true
	count(object.get(parcel_ops(p), "psm_applications", [])) == 0
	w := {"rule_id": "O64-OBL-010", "message": "PSM-Einsatz angegeben, aber keine Angaben zur Bio-Zulässigkeit der Wirkstoffe"}
}

# O64-COD-002/003/005: erwarteter Mähcode aus dem Hauptmähverfahren
expected_mowing_code[pid] := code if {
	some pid, p in o6_4_parcels
	ms := qualifying_mowings(p)
	count(ms) > 0
	ranks := [cfg.mowing_method_rank[e.method] | some e in ms]
	best := min(ranks)
	some e in ms
	cfg.mowing_method_rank[e.method] == best
	code := cfg.mowing_method_to_code[e.method]
}

expected_mowing_code[pid] := "BM0" if {
	some pid, p in o6_4_parcels
	object.get(parcel_ops(p), "mowing_events", null) != null
	count(qualifying_mowings(p)) == 0
}

declared_mowing_code(p) := object.get(mountain_meadow(p), "declared_mowing_code", null)

parcel_warnings[pid] contains w if {
	some pid, p in o6_4_parcels
	some e in mowing_events_of(p)
	not cfg.mowing_method_to_code[object.get(e, "method", "")]
	w := {"rule_id": "O64-COD-002", "message": sprintf("Mähverfahren der Mahd am %v fehlt oder ist unbekannt", [e.date])}
}

violations contains v if {
	some pid, p in o6_4_parcels
	declared := declared_mowing_code(p)
	declared != null
	expected := expected_mowing_code[pid]
	declared != expected
	v := {"rule_id": rule_for_code(expected), "parcel_id": pid, "message": sprintf("beantragter Code %v entspricht nicht der Bewirtschaftung (%v)", [declared, expected])}
}

rule_for_code("BM0") := "O64-COD-003"

rule_for_code(c) := "O64-COD-002" if c != "BM0"

parcel_missing[pid] contains "declared_mowing_code" if {
	some pid, p in o6_4_parcels
	declared_mowing_code(p) == null
}

# o6_4 – Prämienberechnung (Sätze, Kombination, Kürzungsreihenfolge, Modulation, Obergrenze, Zugangskürzung)
package oepul.o6_4

import rego.v1

# O64-PRM-001: Prämiensatz je Mähverfahren und Jahr
premium_rate(code, yr) := r.eur_per_ha if {
	some r in cfg.premium_rates
	r.code == code
	yr >= r.year_from
	rate_year_to_ok(r.year_to, yr)
}

rate_year_to_ok(to, _) if to == null

rate_year_to_ok(to, yr) if {
	is_number(to)
	yr <= to
}

# Wirksamer Mähcode: aus der dokumentierten Bewirtschaftung, sonst beantragter Code
effective_code[pid] := c if {
	some pid, _ in o6_4_parcels
	c := expected_mowing_code[pid]
}

effective_code[pid] := c if {
	some pid, p in o6_4_parcels
	not expected_mowing_code[pid]
	c := declared_mowing_code(p)
	c != null
}

# O64-PRM-003: auf der Einzelfläche nur mit LSE-Abgeltung (1A/1B) kombinierbar
combinable_area_premium(m) if {
	some row in cfg.annex_l_combination_row_4
	row.measure_number == m
	row.combinable == true
	row.landscape_elements_only == false
}

combination_conflicts[pid] contains m if {
	some pid, p in o6_4_parcels
	some m in object.get(parcel_oepul(p), "premium_measures", [])
	m != "4"
	not combinable_area_premium(m)
}

# Abgeltung punktförmiger Landschaftselemente aus 1A/1B (kombinierbar)
le_measure := "1B" if "1B" in farm_measures

le_measure := "1A" if {
	"1A" in farm_measures
	not "1B" in farm_measures
}

le_premium[pid] := total if {
	some pid, p in o6_4_parcels
	m := le_measure
	total := sum([amount |
		some le in object.get(parcel_oepul(p), "point_landscape_elements", [])
		some r in cfg.landscape_element_rates_combinable
		r.measure_number == m
		r.element == le.element
		amount := le.count * r.eur_per_element
	])
}

le_amount(pid) := object.get(le_premium, pid, 0)

# Ausschlussgründe für die o6_4-Prämie eines Schlages
premium_blockers[pid] contains reason if {
	some pid, _ in o6_4_parcels
	not parcel_is_bergmahd[pid]
	reason := "Bergmahd-Definition nicht erfüllt oder Angaben fehlen (O64-ELIG-001..004)"
}

premium_blockers[pid] contains reason if {
	some pid, _ in o6_4_parcels
	some f in object.get(parcel_premium_exclusions, pid, set())
	reason := f.message
}

premium_blockers[pid] contains reason if {
	some pid, _ in o6_4_parcels
	count(object.get(combination_conflicts, pid, set())) > 0
	reason := "unzulässige Maßnahmenkombination auf der Einzelfläche (O64-PRM-003)"
}

premium_blockers[pid] contains "keine Mahd im Antragsjahr – keine Prämie (O64-PRM-002)" if {
	some pid, _ in o6_4_parcels
	object.get(effective_code, pid, "BM0") == "BM0"
}

premium_blockers[pid] contains "Fläche in Naturschutz/Ergebnisorientierte Bewirtschaftung umgewandelt (O64-APP-003)" if {
	some pid, _ in o6_4_parcels
	pid in converted_parcels
}

farm_premium_blockers contains "förderwerbende Person bzw. Betrieb erfüllt Teilnahmevoraussetzungen nicht" if not applicant_eligible

farm_premium_blockers contains "kein gültiger Vertrag für das Antragsjahr" if not contract_active

farm_premium_blockers contains "Abmeldung im laufenden Förderjahr – Maßnahme im Förderjahr nicht gültig (O64-GEN-013)" if exit_in_current_year

farm_premium_blockers contains "Ausschluss aus der Maßnahme nach zweimaliger 100 %-Kürzung (O64-GEN-026)" if excluded_from_measure

farm_premium_blockers contains "Vor-Ort-Kontrolle verweigert (O64-GEN-032)" if control_refused

farm_premium_blockers contains "kein Zahlungsantrag im Antragsjahr (O64-GEN-034)" if payment_claim_missing

premium_parcels[pid] := p if {
	some pid, p in o6_4_parcels
	count(farm_premium_blockers) == 0
	count(object.get(premium_blockers, pid, set())) == 0
}

# Schritt 1: Bruttoprämie je Schlag
gross_premium[pid] := round2(rate * p.area_ha) if {
	some pid, p in premium_parcels
	rate := premium_rate(effective_code[pid], year)
}

gross_premium_total := sum([v | some v in gross_premium])

# Schritt 2: inhaltliche Kürzungen (Punkt 1.12.1.3 SRL, § 48 GSP-AV)
after_content[pid] := v * (1 - (content_reduction_percent / 100)) if {
	some pid, v in gross_premium
}

# Schritt 3: Modulation nach Betriebsgröße (O64-GEN-029)
total_farm_area := object.get(input, ["land", "total_area_ha"], 0)

modulated_area(total) := sum([portion |
	some b in cfg.modulation_bands
	upper := band_upper(b.to_ha, total)
	portion := (max([0, upper - b.from_ha]) * b.payout_percent) / 100
])

band_upper(to, total) := total if to == null

band_upper(to, total) := min([to, total]) if to != null

modulation_factor := modulated_area(total_farm_area) / total_farm_area if total_farm_area > 0

modulation_factor := 1 if total_farm_area <= 0

after_modulation[pid] := v * modulation_factor if {
	some pid, v in after_content
}

# Schritt 4: Obergrenze für Flächenzahlungen je Schlag inkl. LSE (O64-GEN-028)
area_payment_cap_rate := r.eur_per_ha if {
	some r in cfg.area_payment_caps
	r.key == "general"
	year >= r.year_from
	rate_year_to_ok(r.year_to, year)
}

cap_excess[pid] := max([0, (v + le_amount(pid)) - (area_payment_cap_rate * premium_parcels[pid].area_ha)]) if {
	some pid, v in after_modulation
}

after_cap[pid] := max([0, v - cap_excess[pid]]) if {
	some pid, v in after_modulation
}

# Schritt 5: Zugangskürzung bei Flächenausweitung über die Grenze (O64-GEN-023)
premium_area_total := sum([p.area_ha | some p in premium_parcels])

access_factor := area_increase_limit_ha / premium_area_total if {
	premium_area_total > area_increase_limit_ha
} else := 1

net_premium[pid] := round2(v * access_factor) if {
	some pid, v in after_cap
}

net_premium_total := round2(sum([v | some v in net_premium]))

# O64-GEN-027: kein Auszahlungsbetrag ≤ 50 € erforderlich (Ermessen der AMA)
payment_may_be_waived if net_premium_total <= cfg.deadlines.minimum_payment_eur

